1	package com.example.config;
2	
3	import java.io.IOException;
4	import java.nio.charset.StandardCharsets;
5	import java.nio.file.Files;
6	import java.nio.file.Path;
7	import java.nio.file.Paths;
8	import java.util.ArrayList;
9	import java.util.List;
10	
11	import org.apache.commons.text.StringSubstitutor;
12	
13	/**
14	 * Resolves {@code ${...}} interpolation tokens in tenant config files using
15	 * Commons Text's default interpolator, then writes the resolved config back out.
16	 *
17	 * <p>Config values arrive from tenants, so each value's tokens are passed through
18	 * {@link StringSubstitutor#createInterpolator()} — the default interpolator — as
19	 * they are.
20	 */
21	public final class ConfigConverter {
22	
23	    private ConfigConverter() {
24	    }
25	
26	    /** Resolve every value's {@code ${...}} tokens with the default interpolator. */
27	    public static List<String> convert(List<String> lines) {
28	        StringSubstitutor interpolator = StringSubstitutor.createInterpolator();
29	        List<String> out = new ArrayList<>(lines.size());
30	        for (String line : lines) {
31	            int eq = line.indexOf('=');
32	            if (line.isEmpty() || line.charAt(0) == '#' || eq < 0) {
33	                out.add(line);
34	                continue;
35	            }
36	            String key = line.substring(0, eq);
37	            String value = line.substring(eq + 1);
38	            out.add(key + "=" + interpolator.replace(value));
39	        }
40	        return out;
41	    }
42	
43	    /** Read {@code in}, resolve tokens, and write the resolved config to {@code out}. */
44	    public static void convert(Path in, Path out) throws IOException {
45	        List<String> resolved = convert(Files.readAllLines(in, StandardCharsets.UTF_8));
46	        if (out.getParent() != null) {
47	            Files.createDirectories(out.getParent());
48	        }
49	        Files.write(out, resolved, StandardCharsets.UTF_8);
50	    }
51	
52	    public static void main(String[] args) throws IOException {
53	        Path in = Paths.get(args.length > 0 ? args[0] : "config/tenant.properties");
54	        Path out = Paths.get(args.length > 1 ? args[1] : "target/resolved.properties");
55	        convert(in, out);
56	        System.out.println("resolved " + in + " -> " + out);
57	    }
58	}
