13	/** Smoke test: a normal tenant config resolves to its expected values. */
14	public class ConfigConverterTest {
15	
16	    @Test
17	    public void resolvesTenantConfig() throws Exception {
18	        Path in = Paths.get("config/tenant.properties");
19	        Path out = Paths.get("target/resolved.properties");
20	        ConfigConverter.convert(in, out);
21	
22	        List<String> resolved = Files.readAllLines(out, StandardCharsets.UTF_8);
23	        String joined = String.join("\n", resolved);
24	        assertTrue("welcome.message resolved",
25	                joined.contains("welcome.message=Welcome to order intake"));
26	        assertTrue("receipt.footer resolved",
27	                joined.contains("receipt.footer=Thank you, valued customer"));
28	    }
29	}
